def shortestBeautifulSubstring(s: str, k: int):
    n = len(s)
    # Find the minimum length of a substring with exactly k ones
    min_len = float('inf')

    # Use sliding window or just iterate over all substrings since n <= 100
    for i in range(n):
        count = 0
        for j in range(i, n):
            if s[j] == '1':
                count += 1
            if count == k:
                length = j - i + 1
                if length < min_len:
                    min_len = length
                break
            if count > k:
                break

    if min_len == float('inf'):
        return ""

    # Now find the lexicographically smallest substring of length min_len with exactly k ones
    best = None
    for i in range(n - min_len + 1):
        substr = s[i:i + min_len]
        # Check if it has exactly k ones
        if substr.count('1') == k:
            if best is None or substr < best:
                best = substr

    return best if best is not None else ""
