    # Collect all vowels and sort them by ASCII value
    collected_vowels = []
    for ch in s:
        if ch in vowels_set:
            collected_vowels.append(ch)

    # Sort the vowels (ASCII order)
    collected_vowels.sort()

    # Build the result string
    result = []
    vowel_index = 0
    for ch in s:
        if ch in vowels_set:
            result.append(collected_vowels[vowel_index])
            vowel_index += 1
        else:
            result.append(ch)

    return ''.join(result)

