def sortVowels(s: str):
    vowels = set('aeiouAEIOU')
    chars = list(s)
    vs = [c for c in chars if c in vowels]
    vs.sort()
    i = 0
    for j in range(len(chars)):
        if chars[j] in vowels:
            chars[j] = vs[i]
            i += 1
    return ''.join(chars)
